# GENERATED by sparring/gen.py: fuzz mode "wrongcheck".
"""
Protocol-edge sparring bot. MODE selects the misbehaviour:

  random      uniformly random legal action (weighted), random legal raise sizes
  badsize     raises below the minimum, above the stack, to 0/negative, and as floats
  wrongcheck  says "check" when it owes chips and "call" when it owes nothing
  crasher     ~4% of decisions raise an exception, return garbage, or omit the action;
              otherwise plays like a loose random bot

The engine's rules (README): bad replies fold, `check` while owing is a call, a short raise
is lifted to the minimum, an oversized raise is an all-in. tag should survive all of it.
"""

import random

MODE = "wrongcheck"


def legal_random(s):
    owed, can_check = s["amount_owed"], s["can_check"]
    stack = s["your_stack"]
    roll = random.random()
    if roll < 0.25 and not can_check:
        return {"action": "fold"}
    if roll < 0.60:
        return {"action": "check"} if can_check else {"action": "call"}
    if roll < 0.68:
        return {"action": "all_in"}
    lo = s["min_raise_to"]
    hi = stack + s["your_bet_this_street"]
    if lo >= hi:
        return {"action": "all_in"}
    return {"action": "raise", "amount": random.randint(lo, min(hi, lo + 3 * max(s["pot"], lo)))}


def decide(s):
    if s.get("type") == "warmup":
        return {"action": "check"}
    if MODE == "random":
        return legal_random(s)
    if MODE == "badsize":
        roll = random.random()
        stack = s["your_stack"] + s["your_bet_this_street"]
        if roll < 0.15:
            return {"action": "raise", "amount": 1}                       # below min
        if roll < 0.30:
            return {"action": "raise", "amount": stack * 5}               # above stack
        if roll < 0.40:
            return {"action": "raise", "amount": 0}
        if roll < 0.50:
            return {"action": "raise", "amount": -50}
        if roll < 0.60:
            return {"action": "raise", "amount": s["min_raise_to"] + 0.5}  # float
        if roll < 0.70:
            return {"action": "raise", "amount": s["current_bet"]}        # raise to the current bet
        return legal_random(s)
    if MODE == "wrongcheck":
        roll = random.random()
        if roll < 0.5:
            return {"action": "check"}          # a call if we owe chips
        if roll < 0.8:
            return {"action": "call"}           # a check if we owe nothing
        return legal_random(s)
    if MODE == "crasher":
        roll = random.random()
        if roll < 0.015:
            raise RuntimeError("fuzz crash")
        if roll < 0.025:
            return {"action": "bet", "amount": 100}       # unknown action
        if roll < 0.035:
            return {"amount": 100}                         # missing action
        if roll < 0.040:
            return "fold"                                  # not a dict
        return legal_random(s)
    return {"action": "fold"}
